    <script>
        function switchAttenuatorImage(el, src) {
            var mainImg = document.getElementById('mainAttenuatorImg');
            if (mainImg) {
                mainImg.style.opacity = '0';
                setTimeout(function() {
                    mainImg.src = src;
                    mainImg.style.opacity = '1';
                }, 180);
            }
            var thumbs = el.closest('.attenuator-gallery-container').querySelectorAll('.attenuator-thumb-item');
            thumbs.forEach(function(item) {
                item.classList.remove('active');
            });
            el.classList.add('active');
        }
    </script>

